Here's a simple implementation of a sentence-part game in p5.js:

```javascript
// Sentence parts
let parts = [
  { word: "The", x: 100, y: 100, w: 50, h: 20, dragged: false },
  { word: "quick", x: 200, y: 100, w: 50, h: 20, dragged: false },
  { word: "brown", x: 300, y: 100, w: 50, h: 20, dragged: false },
  { word "fox", x: 400, y: 100, w: 50, h: 20, dragged: false },
  { word: "jumps", x: 500, y: 100, w: 50, h: 20, dragged: false },
  { word: "over", x: 600, y: 100, w: 50, h: 20, dragged: false },
  { word: "the", x: 700, y: 100, w: 50, h: 20, dragged: false },
  { word: "lazy", x: 800, y: 100, w: 50, h: 20, dragged: false },
  { word: "dog", x: 900, y: 100, w: 50, h: 20, dragged: false }
];

// Correct sentence parts
let correct = [
  { word: "The", x: 100, y: 100 },
  { word: "quick", x: 200, y: 100 },
  { word: "brown", x: 300, y: 100 },
  { word: "fox", x: 400, y: 100 },
  { word: "jumps", x: 500, y: 100 },
  { word: "over", x: 600, y: 100 },
  { word: "the", x: 700, y: 100 },
  { word: "lazy", x: 800, y: 100 },
  { word: "dog", x: 900, y: 100 }
];

let correctCount = 0;

function setup() {
  createCanvas(1200, 200);
  noStroke();
  rectMode(CORNER);
}

function draw() {
  background(220);
  drawSentence();
  drawCorrectSentence();
  dragParts();
  checkCorrectness();
}

function drawSentence() {
  fill(255);
  textSize(20);
  for (let i = 0; i < parts.length; i++) {
    text(parts[i].word, parts[i].x, parts[i].y);
  }
}

function drawCorrectSentence() {
  fill(0);
  textSize(20);
  for (let i = 0; i < correct.length; i++) {
    text(correct[i].word, correct[i].x, correct[i].y);
  }
}

function dragParts() {
  for (let i = 0; i < parts.length; i++) {
    if (parts[i].dragged) {
      parts[i].x = mouseX;
      parts[i].y = mouseY;
    }
  }
}

function mousePressed() {
  for (let i = 0; i < parts.length; i++) {
    if (dist(mouseX, mouseY, parts[i].x, parts[i].y) < 20) {
      parts[i].dragged = true;
    }
  }
}

function mouseReleased() {
  for (let i = 0; i < parts.length; i++) {
    if (parts[i].dragged) {
      parts[i].dragged = false;
    }
  }
}

function checkCorrectness() {
  for (let i = 0; i < parts.length; i++) {
    if (dist(parts[i].x, parts[i].y, correct[i].x, correct[i].y) < 20) {
      correctCount++;
    }
  }
  if (correctCount === 9) {
    noLoop();
    text("Correct! You did it!", 500, 150);
  }
}
```
This game has a canvas where the sentence parts are drawn. The user can drag the parts to their correct positions. The game checks if the parts are in the correct positions after each drag. If all parts are in the correct positions, the game ends and displays a message.

Here's a simple example of a sentence builder game using p5.js. The game consists of multiple parts of an English sentence, which are draggable. The user can drag the parts into the correct position.

```javascript
// Sentence parts
let sentenceParts = [
  { text: "I", x: 100, y: 200 },
  { text: "am", x: 250, y: 200 },
  { text: "happy", x: 400, y: 200 },
  { text: "because", x: 500, y: 250 },
  { text: "I", x: 650, y: 250 },
  { text: "have", x: 700, y: 250 },
  { text: "gone", x: 800, y: 250 },
  { text: "to", x: 900, y: 300 },
  { text: "bed", x: 1000, y: 300 }
];

// Correct sentence
let correctSentence = "I am happy because I have gone to bed";

// Dragging variables
let dragging = false;
let partBeingDragged;
let offsetx, offsety;

function setup() {
  createCanvas(1200, 400);
  rectMode(CORNER);
  noStroke();

  // Initialize dragging variables
  for (let i = 0; i < sentenceParts.length; i++) {
    sentenceParts[i].index = i;
  }
}

function draw() {
  background(220);
  drawSentenceParts();
  drawCorrectSentence();
}

function drawSentenceParts() {
  for (let i = 0; i < sentenceParts.length; i++) {
    let part = sentenceParts[i];
    fill(255);
    textSize(24);
    text(part.text, part.x, part.y);
  }
}

function drawCorrectSentence() {
  fill(0);
  textSize(24);
  text(correctSentence, 50, 350);
}

function mousePressed() {
  for (let i = 0; i < sentenceParts.length; i++) {
    let part = sentenceParts[i];
    if (dist(mouseX, mouseY, part.x, part.y) < 30) {
      dragging = true;
      partBeingDragged = part;
      offsetx = part.x - mouseX;
      offsety = part.y - mouseY;
      break;
    }
  }
}

function mouseDragged() {
  if (dragging) {
    partBeingDragged.x = mouseX + offsetx;
    partBeingDragged.y = mouseY + offsety;
  }
}

function mouseReleased() {
  if (dragging) {
    for (let i = 0; i < sentenceParts.length; i++) {
      let part = sentenceParts[i];
      if (dist(partBeingDragged.x, partBeingDragged.y, part.x, part.y) < 30) {
        // Swap parts
        let temp = partBeingDragged;
        partBeingDragged = part;
        part = temp;
        partBeingDragged.index = i;
        break;
      }
    }
    dragging = false;
  }
}

function checkWin() {
  let sortedSentenceParts = sentenceParts.slice();
  sortedSentenceParts.sort((a, b) => a.index - b.index);
  let sortedSentence = sortedSentenceParts.map((part) => part.text).join(" ");

  if (sortedSentence === correctSentence.replace(/ /g, ", ")) {
    console.log("Congratulations! You won!");
  }
}
```

In this code, the `sentenceParts` array holds the parts of the sentence. The user can drag these parts around, and when they release the part, it will be swapped with the part at the correct position. The `checkWin` function checks if the sorted sentence parts match the correct sentence.

Note that the `checkWin` function is not called in this code. You can add a call to `checkWin` in the `mouseReleased` function or elsewhere in your code to check if the user has won.

